"""Fit the degree-33 Laurent polynomial and execute source GQSP evolution."""

from pathlib import Path

from examples.synthesis.algorithms.hamiltonian_simulation.hamiltonian_simulation_with_block_encoding.hamiltonian_simulation_qubitization.overview.model import (
    ALPHA,
    TIME,
)
from examples.synthesis.algorithms.hamiltonian_simulation.hamiltonian_simulation_with_block_encoding.hamiltonian_simulation_qubitization.overview.plots import (
    save_comparison,
)
from examples.synthesis.algorithms.hamiltonian_simulation.hamiltonian_simulation_with_block_encoding.hamiltonian_simulation_qubitization.overview.workflow import (
    Projection,
)

from .phases import DEGREE, Factorization, factor
from .workflow import block_projection, evolution_projection

OUTPUT = Path("artifacts/development/gqsp-hamiltonian")


def show_factorization(phases: Factorization) -> None:
    """Report observed coefficient reconstruction and approximation residuals."""
    print(
        "Evolution time, Laurent degree and phase rows:", TIME, DEGREE, len(phases.rows)
    )
    print(f"Completion residual: {phases.completion_residual:.12g}")
    print(f"Stripping residual: {phases.stripping_residual:.12g}")
    print(f"Reconstruction residual: {phases.reconstructed_residual:.12g}")
    print(f"Truncation grid error: {phases.approximation_error:.12g}")


def show_and_save(name: str, label: str, projection: Projection) -> Path:
    """Report absolute native coefficients, scale, and circuit size."""
    print(f"{name} absolute error:", projection.error)
    print(f"{name} raw projected amplitudes:", projection.raw.tolist())
    print(f"{name} rescaling:", projection.scale)
    print(f"{name} qubits:", projection.circuit.n_qubits)
    print(f"{name} IR instructions:", len(projection.circuit.to_ir().instructions))
    return save_comparison(projection, label, OUTPUT / f"{name}.png")


def main() -> None:
    """Execute the original Pauli projection and five-qubit GQSP workflow."""
    phases = factor(TIME * ALPHA)
    show_factorization(phases)
    print(show_and_save("pauli", "Pauli block encoding", block_projection()))
    print(show_and_save("gqsp", "GQSP time evolution", evolution_projection(phases)))


if __name__ == "__main__":
    main()

"""Execute the signed controlled-walk schedule with the native block encoding."""

import torch

import flagquantum as fq
from examples.synthesis.algorithms.hamiltonian_simulation.hamiltonian_simulation_with_block_encoding.hamiltonian_simulation_qubitization.overview.model import (
    DTYPE,
)
from examples.synthesis.algorithms.hamiltonian_simulation.hamiltonian_simulation_with_block_encoding.hamiltonian_simulation_qubitization.overview.quantum import (
    controlled_walk,
    preparation,
)
from examples.synthesis.algorithms.quantum_primitives.gqsp.overview.phases import (
    rotation,
)

from .phases import DEGREE, Factorization


def evolve(data: tuple[float, ...], phases: Factorization) -> fq.Circuit:
    """Apply 33 inverse and 33 forward walk selections on opposite branches."""
    walk = controlled_walk()
    # W = R B for Hermitian B and reflection R, so W† = R W R.
    reflection = torch.diag(torch.tensor((1, 1, 1, 1, 1, -1, -1, -1), dtype=DTYPE))
    inverse = fq.Circuit(5, dtype=DTYPE).any(4, 0, 1, matrix=reflection)
    inverse.compose(walk).any(4, 0, 1, matrix=reflection)
    circuit = fq.Circuit(5, dtype=DTYPE).compose(preparation(data), qubits=(2, 3))
    circuit.any(4, matrix=torch.from_numpy(rotation(phases.rows[0])))
    for step, row in enumerate(phases.rows[1:], start=1):
        if step <= DEGREE:
            circuit.compose(inverse)
        else:
            circuit.x(4).compose(walk).x(4)
        circuit.any(4, matrix=torch.from_numpy(rotation(row)))
    return circuit

"""Check both absolute projections against independent dense references."""

from dataclasses import dataclass

import torch

import flagquantum as fq

from .model import (
    ALPHA,
    DTYPE,
    TIME,
    TOLERANCE,
    expansion,
    fresh_input,
    hamiltonian_matrix,
)
from .quantum import evolution_block, hamiltonian_block


@dataclass(frozen=True)
class Projection:
    """A native Circuit and its raw amplitudes in the all-zero flag sector."""

    circuit: fq.Circuit
    scale: float
    raw: torch.Tensor
    reference: torch.Tensor

    @property
    def error(self) -> float:
        """The absolute vector error with only the declared scale applied."""
        return float(torch.linalg.vector_norm(self.scale * self.raw - self.reference))

    @property
    def fidelity(self) -> float:
        """The squared normalized overlap for reporting."""
        return float(
            (
                torch.vdot(self.raw, self.reference).abs()
                / (self.raw.norm() * self.reference.norm())
            )
            ** 2
        )


def _project(circuit: fq.Circuit, scale: float, reference: torch.Tensor) -> Projection:
    state = fq.run(circuit).statevector().flatten()
    return Projection(circuit, scale, state[:4], reference)


def run_workflow(seed: int = 7) -> tuple[Projection, Projection]:
    """Execute both source projections and check unnormalized complex amplitudes."""
    amplitudes = fresh_input(seed)
    data = tuple(map(float, amplitudes))
    state = amplitudes.to(DTYPE)
    matrix = hamiltonian_matrix()
    poly = expansion()
    first = _project(hamiltonian_block(data), ALPHA, matrix @ state)
    second = _project(
        evolution_block(data, poly),
        poly.scale,
        torch.linalg.matrix_exp(-1j * TIME * matrix) @ state,
    )
    if first.error >= 1e-9:
        raise ValueError(
            f"Hamiltonian projection error {first.error} exceeds tolerance"
        )
    if second.error >= TOLERANCE:
        raise ValueError(f"Evolution projection error {second.error} exceeds tolerance")
    return first, second
